/* case-reports.js: three case reports in the new format the PMCPA intends to use (Case/0395/12/24,
   Case/0440/01/25, Case/0466/01/25), supplied by the PMCPA. Text as supplied; generated by gen_cases.py. */
window.PM_REPORTS = {"0395":{"id":"0395","ref":"CASE/0395/12/24","title":"Allegations regarding information contained on the Vifor Vault website","complainant":"Named, contactable complainant – role not specified","respondent":"CSL Vifor","va":false,"code":2024,"clausesRaised":"5.1, 6.5, 8.5, 16.1 and 26.1","received":"12 and 18 December 2024","panel":"27 November 2025","undertaking":"08 December 2025","appealBoard":"17 December 2025","summaryHtml":"<p>This complaint related to materials on CSL Vifor’s “Vifor Vault” – a website designed for health professionals, which housed materials related to CSL Vifor’s medicines and therapy areas.</p>\n<p>The Panel considered this complaint to allege:</p>\n<ul>\n<li>\n<p>CSL Vifor’s medicine, Ferinject (ferric carboxymaltose), was promoted to the public by a patient leaflet being accessible by a Google search for “<em>vifor vault</em>”.</p>\n</li>\n<li>\n<p>The Vifor Vault included a recording of a presentation that was “<em>approved over </em><em>2 years ago in 2022</em>”.</p>\n</li>\n<li>\n<p>The recording used the term “<em>new</em>” to describe Kapruvia (difelikefalin acetate), when that product had been licensed and available for two years.</p>\n</li>\n</ul>","rulings":[{"clause":"6.5","ruling":"Breach","about":"The word “new” must not be used for products that have been generally available for more than 12 months"},{"clause":"16.1","ruling":"Breach","about":"Promotional material about prescription only medicines directed to a UK audience must comply with all relevant requirements of the Code"},{"clause":"26.1","ruling":"Breach","about":"Promoting a prescription only medicine to the public"},{"clause":"5.1","ruling":"No breach","about":"Requirement to maintain high standards"},{"clause":"8.5","ruling":"No breach","about":"Requirement that materials which are still in use must be recertified at intervals of no more than two years"}],"sections":[{"id":"case-preparation","title":"Case preparation","subs":[],"html":"<p>The PMCPA received a complaint about CSL Vifor from a contactable complainant.</p>\n<p>The complaint is at <strong>Annex A</strong>.</p>\n<p>This complaint related to materials on CSL Vifor’s “Vifor Vault” – a website designed for health professionals, which housed materials related to CSL Vifor’s medicines and therapy areas.</p>\n<p>The Panel considered this complaint to allege:</p>\n<ul>\n<li>\n<p>CSL Vifor’s medicine, Ferinject (ferric carboxymaltose), was promoted to the public by a patient leaflet being accessible by a Google search for “<em>vifor vault</em>”.</p>\n</li>\n<li>\n<p>The Vifor Vault included a recording of a presentation that was “<em>approved over </em><em>2 years ago in 2022</em>”.</p>\n</li>\n<li>\n<p>The recording used the term “<em>new</em>” to describe Kapruvia (difelikefalin acetate), when that product had been licensed and available for two years.</p>\n</li>\n</ul>\n<p>The PMCPA case preparation manager asked CSL Vifor to provide a complete response to the complaint and consider the requirements of Clauses <a href=\"clause.html?clause=5#c5-1\">5.1</a>, 6.5, 8.5, 16.1 and 26.1 of the 2024 Code.</p>\n<p>The response from CSL Vifor is at <strong>Annex B</strong>. CSL Vifor conceded that it was “<em>at risk of breaching Clauses <a href=\"clause.html?clause=16#c16-1\">16.1</a> and 26.1</em>” in relation to allegation 1. However, it did not accept expressly any of the allegations or acknowledge any breaches.</p>\n<p>The case preparation manager referred the case to the Code of Practice Panel to consider and provide its ruling. The Panel considered the information provided by both parties in full.</p>","annex":false},{"id":"panel-ruling","title":"Panel ruling","subs":[{"id":"r-allegation-1-promotion-of-ferinject-to-the-public","t":"Allegation 1 – promotion of Ferinject to the public"},{"id":"r-allegation-2-kapruvia-presentation-recording-approved-more-t","t":"Allegation 2 – Kapruvia presentation recording approved more than two years ago (Clause 8.5)"},{"id":"r-allegation-3-kapruvia-presentation-recording-refers-to-kapru","t":"Allegation 3 – Kapruvia presentation recording refers to Kapruvia as “new”"}],"html":"<h3 id=\"r-allegation-1-promotion-of-ferinject-to-the-public\">Allegation 1 – promotion of Ferinject to the public</h3>\n<p>The complainant alleged that they had searched for “<em>vifor vault</em>” on Google and been able to access a leaflet on the Vifor Vault website that amounted to promotion of Ferinject to the public.</p>\n<p>CSL Vifor submitted that the Vifor Vault website:</p>\n<ul>\n<li>\n<p>was intended for health professionals as a repository for materials related to its medicines and therapy areas</p>\n</li>\n<li>\n<p>was not intended to be accessible via search engines</p>\n</li>\n<li>\n<p>had a pop-up screen before granting access to the site, on which users were asked to self-certify if they are a health professional or a healthcare decision maker (users who clicked ‘no’ were redirected to CSL Vifor UK’s corporate website).</p>\n</li>\n</ul>\n<p>However, CSL Vifor acknowledged in its response:</p>\n<ul>\n<li>\n<p>two documents (pdf files of the Ferinject patient leaflet referred to by the complainant and a ‘Kapruvia Algorithm’) could be viewed <em>without</em> needing to self-certify as a health professional when the search terms “<em>vifor vault</em>” or “<em>vifor vault </em><em>uk</em>” were used within Google</p>\n</li>\n<li>\n<p>both documents were intended for health professionals and should not have been visible to members of the public</p>\n</li>\n<li>\n<p>both documents were “<em>at risk of breaching Clauses <a href=\"clause.html?clause=16#c16-1\">16.1</a> and 26.1</em>” but “<em>very specific search terms were required to access these documents, and entry via the </em><em>vifor vault itself would result in the required disclosures (HCP or not) prior to access to these and all other content</em><em>.</em>”</p>\n</li>\n</ul>\n<p>Although CSL Vifor’s submission referred to two documents (the Ferinject patient leaflet and the Kapruvia Algorithm), the Panel limited its ruling to the Ferinject patient leaflet because that was the subject of the complaint.</p>\n<h4>Clause <a href=\"clause.html?clause=26#c26-1\">26.1</a> – prescription only medicines must not be advertised to the public</h4>\n<p>The Panel relied upon the following points:</p>\n<ul>\n<li>\n<p>Clause <a href=\"clause.html?clause=26#c26-1\">26.1</a> prohibited the advertising of prescription only medicines to the public.</p>\n</li>\n<li>\n<p>Companies can provide non-promotional information to patients about a medicine they have been prescribed, provided that such information complies with the Code (see the supplementary information to Clause <a href=\"clause.html?clause=26#c26-2\">26.2</a> ‘Information to the Public’).</p>\n</li>\n<li>\n<p>It is an established principle that material about a medicine directed at patients who have been prescribed it should not also be accessible to the public unless it is suitable for that audience.</p>\n</li>\n<li>\n<p>The supplementary information to Clause <a href=\"clause.html?clause=16#c16-1\">16.1</a> ‘Website Access’ stated: </p>\n</li>\n<li>\n<p>“<em>Unless access to promotional material about prescription only medicines is limited to health professionals and other relevant decision makers, a pharmaceutical company website or a company sponsored website must provide information for the public as well as promotion to health professionals with the sections for each target audience clearly separated and the intended audience identified</em><em>.</em>”</p>\n</li>\n</ul>\n<p>The Panel concluded that, in the specific context of this case, Ferinject had been promoted to the public because the Ferinject patient leaflet:</p>\n<ul>\n<li>\n<p>was openly accessible to members of the public, and</p>\n</li>\n<li>\n<p>included the brand logo, medicine name and indication.</p>\n</li>\n</ul>\n<p>The Panel acknowledged that the complainant had used a specific search term but considered that it was nevertheless important that material intended for health professionals included a requirement to self-certify as one. CSL Vifor accepted that the complainant in this case had not been required to self-certify as a health professional.</p>\n<p>Given its conclusion that Ferinject had been promoted to the public, the Panel ruled a <strong>breach of Clause <a href=\"clause.html?clause=26#c26-1\">26.1</a></strong>.</p>\n<h4>Clause <a href=\"clause.html?clause=16#c16-1\">16.1</a> – promotional material about prescription only medicines must comply with the Code</h4>\n<p>Clause <a href=\"clause.html?clause=16#c16-1\">16.1</a> required that: </p>\n<ul>\n<li>“<em>promotional material about prescription only medicines directed to a UK audience which is provided on the internet must comply with all relevant requirements of the Code.</em>”</li>\n</ul>\n<p>The supplementary information to Clause <a href=\"clause.html?clause=16#c16-1\">16.1</a> referred to the requirement to ensure information for the public and promotion to health professionals are clearly separated.</p>\n<p>Given its ruling of a breach of Clause <a href=\"clause.html?clause=26#c26-1\">26.1</a> above, and that the requirement to self-certify as a health professional was not in place for the Ferinject patient leaflet, the Panel ruled a <strong>breach of Clause <a href=\"clause.html?clause=16#c16-1\">16.1</a></strong>.</p>\n<h4>Clause <a href=\"clause.html?clause=5#c5-1\">5.1</a> – requirement to maintain high standards</h4>\n<p>In relation to the Clause <a href=\"clause.html?clause=5#c5-1\">5.1</a> requirement to maintain high standards, CSL Vifor submitted that:</p>\n<ul>\n<li>\n<p>this was a technical issue related to how two pdf files were made non-indexable via search engines,</p>\n</li>\n<li>\n<p>this technical issue did not apply to any other content on the Vifor Vault,</p>\n</li>\n<li>\n<p>its intention was for this content to only be visible to the intended audience.</p>\n</li>\n</ul>\n<p>The Panel accepted these submissions from CSL Vifor. The Panel also took account of the very specific search term used by the complainant and that the complaint was limited to the patient leaflet.</p>\n<p>The Panel concluded that CSL Vifor had not failed to maintain high standards and that the breaches of Clauses <a href=\"clause.html?clause=26#c26-1\">26.1</a> and 16.1 were sufficient in relation to this matter. The Panel ruled <strong>no breach of Clause <a href=\"clause.html?clause=5#c5-1\">5.1</a></strong>.</p>\n<h3 id=\"r-allegation-2-kapruvia-presentation-recording-approved-more-t\">Allegation 2 – Kapruvia presentation recording approved more than two years ago (Clause <a href=\"clause.html?clause=8#c8-5\">8.5</a>)</h3>\n<p>In relation to the presentation recording, the complainant alleged that the date of approval was “<em>old</em>” (2022).</p>\n<p>The Panel interpreted the complainant’s allegation to be that:</p>\n<ul>\n<li>\n<p>the presentation recording was certified in November 2022 (the date visible in the screenshot provided by the complainant),</p>\n</li>\n<li>\n<p>this was more than two years before the date of the complaint (December 2024), and</p>\n</li>\n<li>\n<p>this was a breach of the Clause <a href=\"clause.html?clause=8#c8-5\">8.5</a> requirement for materials that are still in use to be recertified at internals of no more than two years.</p>\n</li>\n</ul>\n<p>CSL Vifor submitted that the presentation took place in November 2022, the recording of it was certified in January 2023 and then recertified in March 2023. However, CSL Vifor provided the Panel with a copy of the certificate showing that the recording had actually been recertified on 16 May 2023.</p>\n<p>The Panel was therefore satisfied that, at the time of the complaint, the recording had been certified within the last two years. The Panel ruled <strong>no breach of Clause <a href=\"clause.html?clause=8#c8-5\">8.5</a></strong>.</p>\n<h3 id=\"r-allegation-3-kapruvia-presentation-recording-refers-to-kapru\">Allegation 3 – Kapruvia presentation recording refers to Kapruvia as “new”</h3>\n<p>The complainant alleged that the presentation recording referred to Kapruvia (difelikefalin acetate) as “<em>new</em>” despite it having been licensed and available for two years.</p>\n<h4>Clause <a href=\"clause.html?clause=6#c6-5\">6.5</a> – use of the word “new”</h4>\n<p>Clause <a href=\"clause.html?clause=6#c6-5\">6.5</a> of the Code stated:</p>\n<ul>\n<li>“<em>The word ‘new’ must not be used to describe any product or presentation which has been generally available, or any therapeutic indication which has been promoted, for more than twelve months in the UK.</em>”</li>\n</ul>\n<p>CSL Vifor submitted that:</p>\n<ul>\n<li>\n<p>Kapruvia received its marketing authorisation on 29 April 2022.</p>\n</li>\n<li>\n<p>The word “<em>new</em>” was used in the context of <em>“</em><em>N</em><em>ew therapies for CKD-</em><em>aP</em>” on the outline slide. That slide was shown multiple times, including prior to a discussion of Kapruvia.</p>\n</li>\n<li>\n<p>At the date the meeting was held (November 2022), Kapruvia had been licensed for less than 12 months.</p>\n</li>\n<li>\n<p>At the date of the screenshots that formed this complaint (18 December 2024), Kapruvia had been marketed for more than 12 months.</p>\n</li>\n<li>\n<p>The material at issue was valid because it had been reapproved for two years on 16 March 2023.</p>\n</li>\n<li>\n<p>Viewers of the presentation recording would recognise the date on which the meeting was held and review the video within this context i.e. that Kapruvia was ‘new’ at the time of the recording. </p>\n</li>\n</ul>\n<p>The complainant provided screenshots of some of the presentation slides. CSL Vifor provided the Panel with a copy of the full presentation slides, but not the video itself. Therefore the Panel did not know what commentary (if any) had been made by the speaker about the “<em>new therapies</em>”. However, the Panel considered that it could base its ruling on the content of the slides, including the screenshots that formed part of the complaint.</p>\n<p>The Panel did not have a copy of the webpage on which the presentation recording was hosted. The Panel was therefore unaware of how the presentation recording was described or what information a viewer would have been provided with before accessing the material.</p>\n<p>The Panel took account of the following points:</p>\n<ul>\n<li>\n<p>Kapruvia received its marketing authorisation on <strong>29 April 2022</strong>.</p>\n</li>\n<li>\n<p>The date of reapproval given by CSL Vifor in its letter of response (16 March 2023) was incorrect – the presentation recording was reapproved on <strong>16 May 2023</strong>.</p>\n</li>\n<li>\n<p>The presentation recording was available on the Vifor Vault website at the time of the complaint (<strong>December 2024</strong>).</p>\n</li>\n</ul>\n<p>The complainant’s screenshot showed that the presentation included the date “<em>November 2022</em>” in very small font in the footer of the first slide. However, based on the material provided to it, the Panel considered that it was not immediately clear to a viewer of the video that it was a recording of a meeting that had taken place in November 2022.</p>\n<p>The Panel was concerned that material that used the word “<em>new</em>” had been recertified in May 2023, more than 12 months after Kapruvia received its marketing authorisation.</p>\n<p>The Panel concluded that the word “<em>new</em>” had been used to describe a medicine that had been generally available for more than 12 months in the UK. The Panel therefore ruled a <strong>breach of Clause <a href=\"clause.html?clause=6#c6-5\">6.5</a></strong>.</p>\n<h4>Clause <a href=\"clause.html?clause=5#c5-1\">5.1</a> – requirement to maintain high standards</h4>\n<p>Although the Panel was concerned that the material had been recertified containing the word “<em>new</em>”, the Panel did not consider that there were any additional allegations or factors to suggest that CSL Vifor had failed to maintain high standards in this case. The Panel therefore ruled <strong>no breach of Clause <a href=\"clause.html?clause=5#c5-1\">5.1</a></strong>.</p>","annex":false},{"id":"annex-notes","title":"Annex notes","subs":[],"html":"<p>The Panel used square brackets in Annex A and Annex B to anonymise and redact information in the complaint and response. This is for the purposes of:</p>\n<ul>\n<li>\n<p>protecting the confidentiality of named individuals,</p>\n</li>\n<li>\n<p>protecting company information that is commercially sensitive or confidential,</p>\n</li>\n<li>\n<p>anonymising third parties that have not had a chance to comment on the case, and/or</p>\n</li>\n<li>\n<p>ensuring that material that may be a breach of the Code is not made publicly available when the case report is published.</p>\n</li>\n</ul>\n<p>For similar reasons, any attachments provided to the PMCPA with the complaint and response are not included in this case report.</p>\n<p>The wording of the complaint (Annex A) and the company response (Annex B) is otherwise copied in full below.</p>","annex":false},{"id":"annex-a-the-complaint","title":"Annex A – The complaint","subs":[{"id":"r-further-information-provided-by-the-complainant","t":"Further information provided by the complainant"}],"html":"<p>“Dear SIR</p>\n<p>Please see Ferinject material open to the public which would be promotion to the public. It comes up on search from google when typing vifor vault</p>\n<p>tHE GOOGLE SEARCH IS MISLEADING AS IT SAYS</p>\n<p>CSLVifor – Vifor Vault [Vifor Vault URL and file pathway]</p>\n<p>PDF</p>\n<p>This leaflet explains what Ferinject is, how it is used and what you can expect from your treatment. If you have any additional questions or concerns, ...</p>\n<p>[Link to pdf of Ferinject patient leaflet]</p>\n<p>Regards”</p>\n<p>“Dear Sir</p>\n<p>Additionally I was looking and I came across this</p>\n<p>[Link to webinar]</p>\n<p>Please see webinar.</p>\n<p>[Image showing the title: [Named health professional]: Are we just scratching the surface of CKD-associated pruritus?]</p>\n<p>it looks like the date it has been approved is old ie 2022</p>\n<p>And it uses word NEW when Kapruvia has been licenced for I think 2 years</p>\n<p>Attached are screenshots</p>\n<p>Regards”</p>\n<h3 id=\"r-further-information-provided-by-the-complainant\">Further information provided by the complainant</h3>\n<p>The case preparation manager requested further information from the complainant. The complainant’s response is copied in full below (with redactions as described in the Annex notes section above).</p>\n<p>“I am not tech savvy. This is all very complicated.</p>\n<p><strong>1ST complaint</strong></p>\n<p>This is what I wrote in google</p>\n<p>[screenshot provided showing a Google search for “vifor vault”]</p>\n<p>You can access it yourself, It is the second link on the page</p>\n<p>There is no pop up box</p>\n<p><strong>Second complaint</strong></p>\n<p>After I saw this, I went to explore Vifor’s websites and the vault.</p>\n<p>I saw Kapruvia on the webinar and it being referred to as NEW</p>\n<p>I don’t know the exact pharmacy laws but I would think it needs to be approved so it is relevant, This was approved over 2 years ago in 2022, and is using the word NEW and I have read Kapruvia is not new. It has been licenced and available for 2 years. It is still up on website for people to see and it they are saying this drug is new and people can see it 2 years on, then that is not accurate</p>\n<p>Regards”</p>","annex":true},{"id":"annex-b-csl-vifor-s-response","title":"Annex B – CSL Vifor’s response","subs":[],"html":"<p>“Thank you for your letter dated 10 January 2025 in which you raise two complaints from an individual who has not described themselves or responded to a request to disclose any interest in the matter of complaint or in CSL. </p>\n<p>We note that this is one of a number of complaints communicated to CSL Vifor UK from one or more individuals in a short period of time, and while we are committed to engage in self-regulation and in the complaints process with transparency and professionalism, we would like to highlight that the burden of proof for any complaint resides with the complainant and we hope that only cases where such proof has been provided are raised with us to respond to.</p>\n<p>Furthermore, we fully support the need to accept concerns from individuals who provide limited information where this aligns with the objectives of the Code and the principles of the ABPI. However, we also recognise that complaints can be raised for other, negative, reasons and we rely on the robust application of the constitution and procedure of the Code to ensure all cases are dealt with fairly. We are particularly concerned that the individual has not fully described themselves to you or provided clarity regarding interest with CSL Vifor.</p>\n<p>The 2 complaints raised are:</p>\n<ul>\n<li>\n<p>Public access to Ferinject material hosted on CSL Vifor UK vault, based on a google search of the term ‘vifor vault’</p>\n</li>\n<li>\n<p>Availability of the Nephrology Summit and alleged use of the work ‘new’ in relation to Kapruvia as part of a presentation given by an expert nephrologist.</p>\n</li>\n</ul>\n<p>In your letter you have asked us to consider the requirements of Clauses <a href=\"clause.html?clause=6#c6-5\">6.5</a>, 8.5, 16.1, 26.1 and 5.1 of the 2024 Code.</p>\n<p>Taking each complaint in turn:</p>\n<ol>\n<li>Vifor Vault</li>\n</ol>\n<p>The Vifor Vault is a repository for materials related to CSL Vifor medicines and therapy areas. The site, which consists of a wireframe combined with content (enclosures 1), is intended for HCPs, who are directed to the requested or relevant content by either CSL Vifor’s customer relationship management system or through HCP adverts. The wire frame and content were appropriately reviewed and certified. The site is not intended to be accessible via Google (or other) search engines and we note that the site itself was not visible on the Google search result provided with the complaint or our subsequent searches. When the site was initially set up, checks were made to ensure the site and / or content were not visible via Google search, and we understand that in January 2023 we had to specifically raise the need to have the site made invisible to search engines, to ensure this was in place. </p>\n<p>When accessing the site itself [URL provided], the audience is shown a screen that requests the user to identify whether they are a UK HCP or healthcare decision maker, or neither of these things (enclosure 1 and 2). We believe that due to being accessible only via an invite / link and the pop-up requesting identification as an HCP or healthcare decision maker prior to entry to the site, the content was visible to only the appropriate audience. If the user declared that they were not an HCP or healthcare decision maker, they were redirected to the CSL Vifor UK corporate website [URL provided]. Please note that the Vifor UK Corporate site does not expose or direct the user to any product related content, including publicly available content such as the SPC, as the user is not thought to be searching for any product content.</p>\n<p>We acknowledge that when the specific search term ‘vifor vault’ is entered into Google, it does return a search that includes the Ferinject patient leaflet pdf (enclosure 3) labelled as ‘Downloaded by PMCPA - 5-Ferinject from 2nd link in complaint’ in the attachments included with the letter of complaint dated 10 January 2025. We note that the search result as provided in the letter of complaint is not the same as when we searched for this term but acknowledge that the Ferinject pdf was visible when we searched for ‘vifor vault uk’. </p>\n<p>We acknowledge that while the Vifor Vault web site was not visible, this document (Ferinject patient leaflet pdf), and also the Kapruvia Algorithm pdf (enclosure 3) were visible to the public when the search terms ‘vifor vault’ or ‘vifor vault uk’ were used within Google, without a pop-up requesting identification as an HCP or otherwise. Both documents are intended for HCPs and should not be visible to members of the public, although we note that very specific search terms were required to access these documents, and entry via the vifor vault itself would result in the required disclosures (HCP or not) prior to access to these and all other content.</p>\n<p>Based on your letter and our investigation, on Thurs 16 January 2025 we requested our digital agency to remove the 2 flagged PDFs from view and this was done on the same day. At the same time, we requested a check that the entire site not be visible when searching for Vifor vault or vifor vault uk, which was confirmed on Monday 20 Jan 2025. To be additionally sure that no content was visible, even with a very detailed google search, and due to up-coming SPC changes, we requested that the entire vault site be placed ‘under construction’ and not visible to any user on Friday 24 January 2025. </p>\n<p>The fault appears to be linked to how these specific pdf items were made non-indexable via search engines, which with our prior digital agency was a manual process for each individual item. With a recent system update, the manual ‘fix’ was deleted, making the 2 items visible. This issue did not apply to other content or the site in general.</p>\n<p>As we update our website and content, we will ensure that all appropriate requirements of the ABPI Code are reflected in its content and access to it. </p>\n<p>Based on your letter and our findings, we can see that two items intended for HCPs were visible to members of the public and are, therefore, at risk of breaching Clauses <a href=\"clause.html?clause=16#c16-1\">16.1</a> and 26.1, but this would only be possible through use of very specific search wording.</p>\n<p>Based on the technical nature of the issue and the intent to make our content visible to only the intended audience we do not feel that we have breached Clause <a href=\"clause.html?clause=5#c5-1\">5.1</a> of the ABPI Code. </p>\n<ol start=\"2\">\n<li>The Nephrology Summit</li>\n</ol>\n<p>The CSL Vifor Nephrology Summit was a hybrid promotional meeting held on Friday 25 November 2022 at The Midland Hotel, Manchester and online. The meeting was appropriately reviewed and approved, including the slides for the session created by [named speaker]: Updates on management of CKD-associated pruritus, which is the subject of the complaint (at the meeting titled ‘Are we just scratching the surface of CKD-aP’). </p>\n<p>This session, together with the rest of the meeting was made available on CSL Vifor’s vault website after appropriate review and approval for online use. The recording in question was approved and reapproved on 12 January 2023 and 16 March 2023, respectively (enclosure 6). All content was approved with expiry or reapproval required after 2 years. </p>\n<p>The presentation in question includes an overview of the management of CKD-associated pruritis (CKD-aP) and included mention of the CSL Vifor Medicine Kapruvia (difelikefalin acetate), which received its marketing authorization on 29 April 2022 and was approved by NICE in May 2023. </p>\n<p>The use of the word ‘new’ was as part of the bullet ‘new therapies for CKD-aP’ on the outline slide at the start of [named speaker’s] presentation and prior to each section of [their] talk, including prior to talking about difelikefalin. When the meeting was held, Kapruvia had been licensed for less than 12 months. We recognise that when the content was reviewed by the complainant (and when screenshots were taken on 18 Dec 2024), prior to the letter of complaint, Kapruvia had been marketed for more than 12 months, but the materials in question were valid in that they had been approved for 2 years on 16 March 2023. We would expect the audience of this and other content from the Nephrology Summit to recognise the date on which the meeting was held and review the video within this context, including the linking of difelikefalin with being a ‘new therapy for CKD-aP’ at the time of the meeting. </p>\n<p>We feel that the content of the meeting, including [named speaker’s] presentation, was and continues to be of value to HCPs working with patients with chronic kidney disease and the content does not mislead in terms of patient management or medicine benefits and risk. The content of the meeting was due for withdrawal early in 2025, but has already been withdrawn, and we will ensure that the requirements of Clause <a href=\"clause.html?clause=6#c6-5\">6.5</a> are reflected in the updated content and the meeting remains current and relevant in all ways expected by the ABPI Code.</p>\n<p>Based on the date of the Nephrology Summit meeting and the date of the approval and availability of the recording, we do not believe we have breached Clauses <a href=\"clause.html?clause=6#c6-5\">6.5</a> or 8.5 of the ABPI Code and have, at all times, maintained high standards. </p>\n<p>In summary, we can confirm that due to inadvertent loss of file tagging, two medicine related PDF documents intended for an HCP audience were visible to members of the public, who searched for Vifor Vault, without an alert that the content was for an HCP audience only. These and other content have been removed from view while corrections are put into place. We can also confirm that recorded presentations from the Vifor organized Nephrology Summit, including one by [named speaker], held on the 25 November 2022, were available within the Vifor vault from March 2023. Within this presentation, dated 25 November 2022, difelikefalin is discussed after being introduced as a new therapy for CKD-aP and these materials were approved for 2 years on 16 March 2023.”</p>","annex":true}],"pdf":"https://www.pmcpa.org.uk/media/1stpmix1/case-report-0395-14-jan-26.pdf"},"0440":{"id":"0440","ref":"CASE/0440/01/25","title":"Allegations relating to a meeting venue","complainant":"Named, contactable complainant – role not specified","respondent":"CSL Vifor","va":false,"code":2021,"clausesRaised":"10.1, 5.1 and 2","received":"16 January 2025","panel":"20 November 2025","undertaking":"","appealBoard":"17 December 2025","summaryHtml":"<p>This complaint related to an advisory board held in Los Angeles and attended by a UK health professional.</p>\n<p>The complainant alleged that the venue was “<em>lavish and luxurious</em>”.</p>","rulings":[{"clause":"2","ruling":"No breach","about":"Requirement that activities or materials must not bring discredit upon, or reduce confidence in, the pharmaceutical industry"},{"clause":"5.1","ruling":"No breach","about":"Requirement to maintain high standards at all times"},{"clause":"10.1","ruling":"No breach","about":"Requirement that meeting venues must be appropriate and conducive to the main purpose of the event/meeting"}],"sections":[{"id":"case-preparation","title":"Case preparation","subs":[],"html":"<p>The PMCPA received a complaint about CSL Vifor from a contactable complainant.</p>\n<p>The complaint is at <strong>Annex A</strong>.</p>\n<p>This complaint related to an advisory board held in Los Angeles and attended by a UK health professional.</p>\n<p>The complainant alleged that the venue was “<em>lavish and luxurious</em>”.</p>\n<p>The PMCPA case preparation manager asked CSL Vifor to provide a complete response to the complaint and consider the requirements of Clauses 10.1, 5.1 and 2 of the 2024 Code. CSL Vifor queried the applicable Code year, given that the advisory board at issue took place on 3 June 2024 (before the 2024 Code came into operation) and was advised to refer to the same clauses in the 2021 Code. Although CSL Vifor referred to the 2024 Code in its response, the Panel considered that any difference in the wording of Clauses 10.1, 5.1 and 2 between the two versions of the Code was not significant in this case and therefore made its rulings under the 2021 Code.</p>\n<p>The response from CSL Vifor is at <strong>Annex B</strong>. This includes further information provided by CSL Vifor following a request by the case preparation manager. CSL Vifor disputed all allegations.</p>\n<p>The case preparation manager referred the case to the Code of Practice Panel to consider and provide its ruling. The Panel considered the information provided by both parties in full.</p>","annex":false},{"id":"panel-ruling","title":"Panel ruling","subs":[],"html":"<p>The Panel agreed with the case preparation manager’s interpretation that the complainant had misspelt the name of the health professional by a single letter and considered that the complainant had provided sufficient information for CSL Vifor and the Panel to be clear as to what their complaint referred to. The Panel was disappointed that CSL Vifor did not initially respond in full to this complaint.</p>\n<p>CSL Vifor submitted that a UK health professional flew to the USA on 2 June 2024 to chair an advisory board meeting titled “<em>Communicating the Risk of Hypophosphatemia with FCM</em>”. CSL Vifor paid for one night of accommodation for the health professional at the meeting venue; the health professional returned home after the meeting.</p>\n<p>The complainant alleged that the meeting venue was a “<em>lavish and luxurious</em>” hotel.</p>\n<p>From the screenshot taken by the case preparation manager of the URL provided by the complainant, the Panel observed that the hotel at issue was part of a collection of independent hotels within the portfolio of a large hotel company and was described as:</p>\n<ul>\n<li>\n<p>Being “<em>just 3 miles away</em>” from Los Angeles International Airport</p>\n</li>\n<li>\n<p>having “<em>elegant accommodation</em>”</p>\n</li>\n<li>\n<p>being “<em>surrounded by a green Golf Club where guests can play</em>”</p>\n</li>\n<li>\n<p>having “<em>an outdoor pool and a well-equipped gym</em>”.</p>\n</li>\n</ul>\n<p>The Panel did not have a screenshot of the webpage provided by CSL Vifor in its response to the request from the case preparation manager for further information. While conscious that the webpage may have changed in the intervening period, the Panel noted the following points from the content of the current live website:</p>\n<ul>\n<li>\n<p>“<em>A Lifestyle Hotel</em>”</p>\n</li>\n<li>\n<p>“…<em>inviting and spacious meeting spaces ideal for infusing your most important events with a focused, sophisticated vibe</em>”</p>\n</li>\n<li>\n<p>“…<em>a private </em><em>9-hole </em><em>golf course </em><em>across 2</em><em>6-acres</em>”</p>\n</li>\n</ul>\n<p>In its letters of response, CSL Vifor submitted that the meeting venue:</p>\n<ul>\n<li>\n<p>was a four-star hotel</p>\n</li>\n<li>\n<p>was a convenient location for the attendees because of its proximity to LAX airport in Los Angeles</p>\n</li>\n<li>\n<p>provided the appropriate meeting and conference facilities</p>\n</li>\n<li>\n<p>was queried by one of its senior UK medical employees but subsequently approved by them.</p>\n</li>\n</ul>\n<p>CSL Vifor also provided the Panel with a copy of an email exchange between the senior UK medical employee and several Global colleagues regarding the approval of the arrangements for the UK health professional. The Panel took account of the following points:</p>\n<ul>\n<li>\n<p>The senior UK medical employee queried, among other things, the choice of venue: “<em>I note [named hotel]. And it seems a lavish venue and disproportionate to what is being held here. What is the reason we are flying [named health professional] to the US?</em>”</p>\n</li>\n<li>\n<p>The initial response to this query explained the rationale for the meeting being held in the US but did not address the choice of the specific hotel.</p>\n</li>\n<li>\n<p>The senior UK medical employee asked for their Global colleagues’ views on the meeting venue, stating: “<em>The greatest risk with the meeting is the venue [link to hotel website]. Because it is a beach hotel and has a golf course and in a </em><em>complaint may or may not be a breach depending on interpretation.</em>” They cited some wording from Clause 10.1 of the Code and its supplementary information.</p>\n</li>\n<li>\n<p>One of the Global employees responded:\n<em>“</em><em>● It is not a beach hotel, but is a hotel (formerly [hotel brand]) which is 5 mins from LAX airport and is a part of a corporate office park. The golf course is an add-on for hosting corporate team building events.</em>\n<em>● The webpage of the hotel for obvious competitive reasons lists it the way it does.</em>\n<em>● The proximity to LAX airport as a matter of fact lends a risk to us that we will be close to the flight path, but we zeroed in on this in light of the fact that we wanted it close to the airport and a hotel with the least number of frills.”</em></p>\n</li>\n<li>\n<p>The senior UK medical employee subsequently approved the arrangements for the UK health professional, including £175 for the overnight stay at the hotel. They included a comment on the approval system: “<em>there is a risk with venue chosen as already emailed to global team</em>”.</p>\n</li>\n</ul>\n<p>The Panel did not have before it any information regarding the invitation to the UK health professional to participate in the meeting.</p>\n<p>Clause 10.1 of the Code required, among other things, that the venue must be appropriate and conducive to the main purpose of the event/meeting; lavish, extravagant or deluxe venues must not be used.</p>\n<p>The Panel considered that companies had to be mindful of the impression created by all the arrangements for a meeting, including the venue. A four-star hotel that included an on-site golf course and outdoor pool, such as the one at issue, would have to be carefully checked to ensure that its facilities were appropriate, bearing in mind the intended delegates, the nature of the meeting and the venue’s reputation both locally and nationally.</p>\n<p>In reaching its determination, the Panel relied upon the following:</p>\n<ul>\n<li>\n<p>The UK health professional was accommodated for only one night at the same hotel as was used for the advisory board meeting the following day. The advisory board meeting ran from 08.30 to 16.00. The Panel did not have before it any information regarding the arrival and departure times of the UK health professional’s flights.</p>\n</li>\n<li>\n<p>The complainant did not give any specific reasons to substantiate their allegation that the hotel was “<em>lavish and luxurious</em>”.</p>\n</li>\n<li>\n<p>The hotel was not a “<em>beach hotel</em>”: the word “<em>beach</em>” was included in the hotel name because it referred to the name of the city in which the hotel was located (within Los Angeles County).</p>\n</li>\n<li>\n<p>The hotel appeared to be located relatively near to an international airport and several of the meeting attendees were travelling from overseas.</p>\n</li>\n<li>\n<p>The complainant provided no evidence that the hospitality costs involved in the meeting exceeded the level which the recipient would normally adopt when paying for themselves.</p>\n</li>\n<li>\n<p>The agenda for the meeting ran from 08.30 to 16.00, including an hour for lunch, but did not appear to include any other leisure activities or hospitality.</p>\n</li>\n</ul>\n<p>The Panel queried whether consideration had been given to the use of technology to avoid international travel and considered, if an in-person meeting was deemed essential, that it would have been preferable if a venue without a golf course had been chosen.</p>\n<p>The Panel noted that the complainant bore the burden of proving their complaint on the balance of probabilities and that all complaints were judged on the evidence provided by the parties. While the Panel had some concerns about the meeting venue, on balance, the Panel concluded that the complainant had not established that the venue was “<em>lavish and </em><em>luxurious</em>” and inappropriate in relation to the requirements of Clause 10.1.</p>\n<p>The Panel ruled <strong>no breach of Clause 10.1</strong>.</p>\n<p>Noting its ruling of no breach of Clause 10.1, the Panel did not consider that the circumstances of this case indicated that high standards had not been maintained or that CSL Vifor had brought discredit upon, or reduced confidence in, the pharmaceutical industry.</p>\n<p>The Panel ruled <strong>no breach of Clause 5.1 and </strong>no breach of Clause 2**.</p>","annex":false},{"id":"annex-notes","title":"Annex notes","subs":[],"html":"<p>The Panel used square brackets in Annex A and Annex B to anonymise and redact information in the complaint and response. This is for the purposes of:</p>\n<ul>\n<li>\n<p>protecting the confidentiality of named individuals,</p>\n</li>\n<li>\n<p>protecting company information that is commercially sensitive or confidential,</p>\n</li>\n<li>\n<p>anonymising third parties that have not had a chance to comment on the case, and/or</p>\n</li>\n<li>\n<p>ensuring that material that may be a breach of the Code is not made publicly available when the case report is published.</p>\n</li>\n</ul>\n<p>For similar reasons, any attachments provided to the PMCPA with the complaint and response are not included in this case report.</p>\n<p>The wording of the complaint (Annex A) and the company response (Annex B) is otherwise copied in full below.</p>","annex":false},{"id":"annex-a-the-complaint","title":"Annex A – The complaint","subs":[],"html":"<p>“[Named health professional] attended advisory board in 3rd or 4<sup>th </sup>June in Los Angeles</p>\n<p>Title of Ad board:  Risk of Hypophosphataemia</p>\n<p>Hotel: lavish and luxurious- [named hotel in Los Angeles]</p>\n<p>[URL provided leading to the details of the named hotel on a hotel booking website]</p>\n<p>This is against the ABPI code.  luxurious venue and hotel”</p>","annex":true},{"id":"annex-b-csl-vifor-s-response","title":"Annex B – CSL Vifor’s response","subs":[{"id":"r-further-information-from-csl-vifor","t":"Further information from CSL Vifor"}],"html":"<p>“Thank you for your letter dated 17 January 2025 in which you raise a complaint from a contactable individual who does not describe themselves and simply provides the name of a hotel and describes it as lavish and luxurious and claiming that ‘this is against the ABPI Code’. We are unsure whether the individual has any interest or relationship with CSL or CSL Vifor UK and request that you confirm this.</p>\n<p>We note that this is one of a number of complaints communicated to CSL Vifor UK from one or more individuals in a short period of time, and while we are committed to engage in self-regulation and in the complaints process with transparency and professionalism, we would like to highlight that the burden of proof for any complaint resides with the complainant and we hope that only cases where such proof has been provided are raised with us to respond to.</p>\n<p>Furthermore, we fully support the need to accept concerns from complainants where this aligns with the objectives of the Code and the principles of the ABPI. However, we also recognise that complaints can be raised for other, negative, reasons and we rely on the robust application of the constitution and procedure of the Code to ensure all cases are dealt with fairly.</p>\n<p>In your letter you have asked us to consider the requirements Clauses 10.1, 5.1 and 2 of the 2024 Code, but we are unsure as to what evidence you have received that suggests there are risks that these Clauses have been breached, other than a link to a 4 star hotel and the claim that this is lavish and luxurious and, therefore a breach of the ABPI Code.</p>\n<p>Our concerns and uncertainties aside, we can confirm that CSL Vifor UK, including any linked CSL organization or subsidiary, did not send “[health professional named in the complaint]” to an advisory board in Los Angeles on 3 or 4 June 2024.</p>\n<p>We hope that this assurance addresses your letter and we can consider this matter closed.</p>\n<p>For completeness and full transparency, as per our response to Case 0434/12/24, we can confirm that [health professional with a surname with one letter different to that given by the complainant] was invited to participate in an advisory board on the 3rd June 2024 at [the hotel named by the complainant], Los Angeles, California by the Global Iron Therapy team to Chair the meeting titled: Communicating the Risk of Hypophosphatemia With FCM.</p>\n<p>There were 11 international experts in attendance from across the world and [named health professional] flew out to the USA on the 2nd June and returned home after the meeting on the 3rd June (one night stay). [They were] accommodated for the one night at the meeting venue, the 4 star [named hotel], which served as a convenient location for the attendees and provided the appropriate meeting and conference facilities.</p>\n<p>The meeting agenda and content were approved by [a global senior medical employee]. However, the meeting was also reviewed and approved by the then CSL Vifor [senior UK medical employee] This approval was recorded within the meetings and expenses approval system, Vinci, and the attachments provided for review included the HCP contract, meeting arrangements, invite with approval certificate, agenda with approval certificate, attendees and content showreel with approval certificate. A question about the meeting venue appears to have been raised by the [senior UK medical employee], but the meeting was subsequently approved by [them], probably due to the fact that the hotel was appropriate in that it is a 4 star hotel, convenient in terms of location and appropriate in terms of the attendees and meeting facilities.</p>\n<p>We do have documentation supporting our position but have not provided them given that the complaint is about a “[health professional named in the complaint]” and provides no evidence to require provision of counter evidence.</p>\n<p>We, therefore, cannot see any grounds for breaches of the ABPI Code and refute any suggestion of breaches of Clauses 10.1, 5.1 and 2 of the 2024 Code.”</p>\n<h3 id=\"r-further-information-from-csl-vifor\">Further information from CSL Vifor</h3>\n<p>The case preparation manager requested further information from CSL Vifor on the basis that the complainant had misspelt the name of the health professional by one letter, and in line with the overriding objective and the spirit of the Code.</p>\n<p>The response from CSL Vifor is copied in full below (with anonymisation and redactions as described in the Annex notes section above).</p>\n<p>“Thank you for your email received 28 February 2025 in which you request documentation to support justification for the venue.</p>\n<p>The Advisory Board included 11 advisors, including [named health professional], who served as the meeting chair. The review of the meeting included the agenda, objectives, and the venue, which was chosen for the following reasons:</p>\n<ul>\n<li>\n<p>The attendees were from across the globe, including Australia and included 5 who were North America based</p>\n</li>\n<li>\n<p>The proximity of the venue to LAX airport</p>\n</li>\n<li>\n<p>E mail discussion about the meeting venue more widely (than location)</p>\n</li>\n</ul>\n<p>The venue was assessed via the following link [URL provided] (as per the [senior UK medical employee’s] comment in Enclosure 1.</p>\n<p>Based on the question raised by [the senior UK medical employee], the responses given and the subsequent approval by the [senior UK medical employee], we believe that the oversees [<em>sic</em>] engagement of a UK HCP, the meeting itself and the meeting venue underwent the review and approval required by the UK Code and there have not been breaches of Clauses 10.1, 5.1 and 2 of the 2024 Code.”</p>\n<p>Page <strong>2 of </strong>2**</p>","annex":true}],"pdf":""},"0466":{"id":"0466","ref":"CASE/0466/01/25","title":"A video on the website of a medical journal","complainant":"Voluntary admission","respondent":"Pierre Fabre Ltd","va":true,"code":2024,"clausesRaised":"2, 5.1, 5.6, 8.1, 11.2, 12.1, 12.6, and 15.6","received":"31 January 2025","panel":"20 November 2025","undertaking":"28 November 2025","appealBoard":"17 December 2025","summaryHtml":"<p>This voluntary admission related to a video that appeared on the website of a medical journal. Pierre Fabre submitted that the video had, in error, been promoted to UK health professionals by email.</p>\n<p>The Panel considered that, in the voluntary admission, Pierre Fabre acknowledged that:</p>\n<ul>\n<li>\n<p>The arrangements for the activity were not strictly arm’s length.</p>\n</li>\n<li>\n<p>The promotional video for Braftovi (encorafenib) had not been certified (Clause <a href=\"clause.html?clause=8#c8-1\">8.1</a>).</p>\n</li>\n<li>\n<p>The video contained no prescribing information (Clause <a href=\"clause.html?clause=12#c12-1\">12.1</a>) or adverse event reporting statement (Clause <a href=\"clause.html?clause=12#c12-6\">12.6</a>).</p>\n</li>\n<li>\n<p>The declaration of involvement was not sufficiently clear as to Pierre Fabre’s involvement (Clause <a href=\"clause.html?clause=5#c5-6\">5.6</a>).</p>\n</li>\n<li>\n<p>The promotional nature of the video had been disguised (Clause <a href=\"clause.html?clause=15#c15-6\">15.6</a>).</p>\n</li>\n<li>\n<p>The video promoted Braftovi for an unlicensed indication (Clause <a href=\"clause.html?clause=11#c11-2\">11.2</a>).</p>\n</li>\n<li>\n<p>High standards had not been maintained (Clause <a href=\"clause.html?clause=5#c5-1\">5.1</a>).</p>\n</li>\n<li>\n<p>The Panel may want to consider the requirements of Clause <a href=\"clause.html?clause=2\">2</a>.</p>\n</li>\n</ul>","rulings":[{"clause":"5.1","ruling":"Breach","about":"Failing to maintain high standards"},{"clause":"5.6","ruling":"Breach","about":"Failing to be sufficiently clear as to the company’s role and involvement"},{"clause":"8.1","ruling":"Breach","about":"Failing to certify promotional material"},{"clause":"11.2","ruling":"Breach","about":"Promoting a medicine for an unlicensed indication"},{"clause":"12.1","ruling":"Breach","about":"Failing to include prescribing information"},{"clause":"12.6","ruling":"Breach","about":"Failing to include the prominent adverse event reporting statement"},{"clause":"15.6","ruling":"Breach","about":"Disguising promotional material"},{"clause":"2","ruling":"No breach","about":"Requirement that activities or materials must not bring discredit upon, or reduce confidence in, the pharmaceutical industry"}],"sections":[{"id":"case-preparation","title":"Case preparation","subs":[],"html":"<p>The PMCPA received a voluntary admission from Pierre Fabre Ltd.</p>\n<p>The voluntary admission is at <strong>Annex A</strong>.</p>\n<p>This case related to a video that appeared on the website of a medical journal. Pierre Fabre submitted that the video had, in error, been promoted to UK health professionals by email.</p>\n<p>The Panel considered that, in the voluntary admission, Pierre Fabre acknowledged that:</p>\n<ul>\n<li>\n<p>The arrangements for the activity were not strictly arm’s length.</p>\n</li>\n<li>\n<p>The promotional video for Braftovi (encorafenib), had not been certified (Clause <a href=\"clause.html?clause=8#c8-1\">8.1</a>).</p>\n</li>\n<li>\n<p>The video contained no prescribing information (Clause <a href=\"clause.html?clause=12#c12-1\">12.1</a>) or adverse event reporting statement (Clause <a href=\"clause.html?clause=12#c12-6\">12.6</a>).</p>\n</li>\n<li>\n<p>The declaration of involvement was not sufficiently clear as to Pierre Fabre’s involvement (Clause <a href=\"clause.html?clause=5#c5-6\">5.6</a>).</p>\n</li>\n<li>\n<p>The promotional nature of the video had been disguised (Clause <a href=\"clause.html?clause=15#c15-6\">15.6</a>).</p>\n</li>\n<li>\n<p>The video promoted Braftovi for an unlicensed indication (Clause <a href=\"clause.html?clause=11#c11-2\">11.2</a>).</p>\n</li>\n<li>\n<p>High standards had not been maintained (Clause <a href=\"clause.html?clause=5#c5-1\">5.1</a>).</p>\n</li>\n<li>\n<p>The Panel may want to consider the requirements of Clause <a href=\"clause.html?clause=2\">2</a>.</p>\n</li>\n</ul>\n<p>The PMCPA case preparation manager asked Pierre Fabre to provide any further comments on this matter in relation to the requirements of Clauses <a href=\"clause.html?clause=2\">2</a>, 5.1, 5.6, 8.1, 11.2, 12.1, 12.6 and 15.6 of the 2024 Code.</p>\n<p>The response from Pierre Fabre is at <strong>Annex B</strong>. Pierre Fabre accepted breaches of Clauses <a href=\"clause.html?clause=5#c5-1\">5.1</a>, 5.6, 8.1, 11.2, 12.1, 12.6 and 15.6 in relation to the above allegations.</p>\n<p>The case preparation manager referred the case to the Code of Practice Panel to consider and provide its ruling. The Panel considered the information provided by Pierre Fabre in full.</p>","annex":false},{"id":"panel-ruling","title":"Panel ruling","subs":[{"id":"r-was-the-video-within-scope-of-the-uk-code","t":"Was the video within scope of the UK Code?"},{"id":"r-were-the-sponsorship-arrangements-arm-s-length","t":"Were the sponsorship arrangements arm’s length?"},{"id":"r-was-the-video-promotional-for-braftovi-encorafenib","t":"Was the video promotional for Braftovi (encorafenib)?"},{"id":"r-requirements-for-promotional-material","t":"Requirements for promotional material"},{"id":"r-promoting-an-unlicensed-indication-clause-11-2","t":"Promoting an unlicensed indication (Clause 11.2)"},{"id":"r-declaration-of-involvement-clause-5-6","t":"Declaration of involvement (Clause 5.6)"},{"id":"r-disguised-promotion-clause-15-6","t":"Disguised promotion (Clause 15.6)"},{"id":"r-overall","t":"Overall"}],"html":"<p>Pierre Fabre submitted that a medical journal had approached its parent company, Pierre Fabre Medicament, with a sponsorship proposal for an activity associated with a European medical conference taking place in September 2024.</p>\n<p>The written proposal described the activity as an:</p>\n<ul>\n<li><em>“</em><em>…</em><em>educational project focused on advancements in the treatment of BRAFV600-mutant metastatic non-small cell lung cancer (NSCLC) and the latest insights on targeted therapies for metastatic melanoma.”</em></li>\n</ul>\n<p>One of the outputs from the project was a video recording of interviews with several key opinion leaders (“KOLs”). That video would then be placed on the medical journal’s website and promoted through a targeted email campaign to oncology specialists who had subscribed to its platform.</p>\n<p>Pierre Fabre submitted that, in error, UK health professionals had been included in the distribution of the email. Pierre Fabre voluntarily admitted to several breaches of the Code in relation to the video.</p>\n<p>The Panel considered that the first three questions to be addressed were:</p>\n<ul>\n<li>\n<p>Was the video within the scope of the UK Code?</p>\n</li>\n<li>\n<p>Had the intended arm’s-length arrangements been compromised?</p>\n</li>\n<li>\n<p>Was the video promotional?</p>\n</li>\n</ul>\n<h3 id=\"r-was-the-video-within-scope-of-the-uk-code\">Was the video within scope of the UK Code?</h3>\n<p>Pierre Fabre Medicament (headquartered in France) had instructed the medical journal that UK health professionals should be excluded from the distribution list for the email notification. The Panel noted that this instruction had been recorded in a briefing document to the medical journal. In answer to the question <em>“</em><em>Any countries excluded from promotional activities</em>”, the briefing document stated: <em>“UK to be excluded from send out”.</em><em> </em>Pierre Fabre submitted that it appeared that there was limited or no contact by Pierre Fabre Medicament to check if these instructions had been followed.</p>\n<p>Pierre Fabre submitted that the video was made available on the medical journal website on 26 September 2024. On 10 October 2024, a UK employee registered as a health professional on the medical journal’s website received an email directing them to the video.</p>\n<p>On investigation with the medical journal, Pierre Fabre submitted that:</p>\n<ul>\n<li>\n<p>the email distribution list had been created before the briefing document, and</p>\n</li>\n<li>\n<p>due to an oversight by the medical journal’s project manager, the distribution list had not been updated to exclude UK health professionals.</p>\n</li>\n</ul>\n<p>The Panel concluded that the video was in scope of the UK Code because:</p>\n<ul>\n<li>\n<p>The sponsorship agreement was between Pierre Fabre Medicament and the medical journal (a UK company).</p>\n</li>\n<li>\n<p>Pierre Fabre Medicament was the parent company of Pierre Fabre Ltd.</p>\n</li>\n<li>\n<p>It is a well-established principle of the Code that UK pharmaceutical companies are responsible for the activities of their overseas affiliates, including parent companies, if such activities relate to UK health professionals.</p>\n</li>\n<li>\n<p>The email notification directing recipients to the video had been sent to 30,000 health professionals, of which 2,523 were based in the UK.</p>\n</li>\n</ul>\n<h3 id=\"r-were-the-sponsorship-arrangements-arm-s-length\">Were the sponsorship arrangements arm’s length?</h3>\n<p>Pierre Fabre submitted that the arrangements for the sponsored activity between Pierre Fabre Medicament and the medical journal had been intended to be arm’s length.</p>\n<p>The Panel considered that a company could sponsor material produced by an independent organisation which mentioned that company’s products. However, for a company to avoid being responsible under the Code for the content of that material, it is essential that there is a strictly arm’s-length arrangement between the parties.</p>\n<p>Pierre Fabre conceded that any arm’s-length arrangement had been compromised because Pierre Fabre Medicament provided a list of suggested KOLs to participate in the interviews and would also receive a <em>“…statistics report, a QR Code and invitations for Pierre Fabre to share content”</em> as specified in the sponsorship agreement.</p>\n<p>Based upon the following extracts from the sponsorship documentation, the Panel did not consider this arrangement to be strictly arm’s length:</p>\n<ul>\n<li>\n<p>Pierre Fabre was referred to as “<em>the client</em>” in the proposal from the medical journal.</p>\n</li>\n<li>\n<p>The medical journal agreed to provide Pierre Fabre with <em>“a content analytics breakdown that gives statistics on performance”</em>.</p>\n</li>\n<li>\n<p>At no additional cost to Pierre Fabre, the medical journal agreed to host a recording of Pierre Fabre’s symposium from the same European conference and promote it through its digital channels.</p>\n</li>\n<li>\n<p>A section of the sponsorship agreement relating to the video stated: “<em>KOL Interview Video Recording during a key conference to amplify communications on a topic of your choice</em>” (emphasis added by the Panel).</p>\n</li>\n<li>\n<p>A section of the sponsorship agreement titled ‘Sponsorship Benefits’ stated: </p>\n</li>\n<li>\n<p>“<em>In exchange for the Sponsorship, Recipient </em>[medical journal] <em>agrees to provide to Sponsor</em><em> </em>[Pierre Fabre]<em> tangible benefits…</em>” and </p>\n</li>\n<li>\n<p>“<em>Sponsorship benefits include a statistics report, a QR code and invitations for Pierre Fabre to share content, along with a clear disclaimer</em>”.</p>\n</li>\n<li>\n<p>Email correspondence indicated that Pierre Fabre was expected to:</p>\n</li>\n<li>\n<p><em>“Fill in the briefing document for the KOL Interview Recordings with topic expectations and the 2 KOLs details</em><em> … This will then allow Pierre Fabre to take on the hands-off approach after as our medical writer will put together the outline for the interview”.</em></p>\n</li>\n<li>\n<p><em>“Secure both KOLs and inform </em><em>[named medical journal] to when we’re able to reach out”</em>.</p>\n</li>\n</ul>\n<p>In combination, these factors convinced the Panel that there had not been a strictly arm’s length agreement between the parties because of Pierre Fabre’s ability to influence significantly the content of the video, suggest which KOLs should be interviewed, and liaise directly with those KOLs. Pierre Fabre also received benefits, such as detailed reports containing analytical data and having its own symposium hosted on the medical journal’s website.</p>\n<p>The Panel concluded that Pierre Fabre was liable for the content of the video under the Code, given the actions of its overseas parent company, as acknowledged in the voluntary admission.</p>\n<h3 id=\"r-was-the-video-promotional-for-braftovi-encorafenib\">Was the video promotional for Braftovi (encorafenib)?</h3>\n<p>Pierre Fabre admitted that the video was promotional because it referred to the use of BRAF inhibitors in the treatment of NSCLC and melanoma, and Pierre Fabre had a medicine in this class (encorafenib).</p>\n<p>The video was titled ‘Shared insights on treating BRAFV600-mutant metastatic cancers’ and featured the following statements from the KOLs being interviewed:</p>\n<ul>\n<li>\n<p><em>“…</em><em>encorafenib turned out to be stat</em><em>istically significantly better…”</em></p>\n</li>\n<li>\n<p><em>“…</em><em>encorafenib is by far the strongest of BRAF inhibitors</em><em>…”</em></p>\n</li>\n<li>\n<p><em>“…for </em><em>encorafenib and </em><em>[other named drug] there is no specific adverse event which you can dedicate to the BRAF inhibitor…”</em></p>\n</li>\n<li>\n<p><em>“…</em><em>so in </em><em>general the toxicity is nicely</em><em> </em>[sic]<em> to manage…” </em>(in relation to encorafenib)</p>\n</li>\n<li>\n<p><em>“…no </em><em>long-term toxicities which have been described…” </em>(in relation to encorafenib).</p>\n</li>\n</ul>\n<p>In the context of a video discussing the treatment of BRAFV600-mutant metastatic cancers, the Panel considered these positive statements about encorafenib to be clearly promotional.</p>\n<h3 id=\"r-requirements-for-promotional-material\">Requirements for promotional material</h3>\n<h4>Certification (Clause <a href=\"clause.html?clause=8#c8-1\">8.1</a>)</h4>\n<p>Clause <a href=\"clause.html?clause=8#c8-1\">8.1</a> stated:</p>\n<ul>\n<li><em>“Promotional material must not be issue</em><em>d unless its final form, to which no subsequent amendments will be made, has been certified by one person on behalf of the company…”.</em></li>\n</ul>\n<p>Pierre Fabre admitted that this promotional video had not been certified as required by Clause <a href=\"clause.html?clause=8#c8-1\">8.1</a>.</p>\n<p>The Panel ruled a <strong>breach of Clause <a href=\"clause.html?clause=8#c8-1\">8.1</a></strong>.</p>\n<h4>Prescribing information (Clause <a href=\"clause.html?clause=12#c12-1\">12.1</a>)</h4>\n<p>Clause <a href=\"clause.html?clause=12#c12-1\">12.1</a> required that:</p>\n<ul>\n<li><em>“The prescribing information listed in Clause <a href=\"clause.html?clause=12#c12-2\">12.2</a> must be provided in a clear and legible manner in all promotional material for a medicine except abbreviated a</em><em>dvertisements.”</em></li>\n</ul>\n<p>Pierre Fabre admitted that the promotional video did not include prescribing information.</p>\n<p>The Panel agreed and ruled a <strong>breach of Clause <a href=\"clause.html?clause=12#c12-1\">12.1</a></strong>.</p>\n<h4>Adverse event reporting statement (Clause <a href=\"clause.html?clause=12#c12-6\">12.6</a>)</h4>\n<p>Clause <a href=\"clause.html?clause=12#c12-6\">12.6</a> required that:</p>\n<ul>\n<li><em>“All promotional material must include the prominent statement</em><em> ‘Adverse events should be reported. Reporting forms and information can be found at [website address which </em><em>links directly to the MHRA Yellow Card site</em><em>]</em><em>. Adverse events should also be reported to [relevant pharmaceutical company].</em><em>’</em><em>”</em></li>\n</ul>\n<p>Pierre Fabre admitted that the promotional video did not include the adverse event reporting statement.</p>\n<p>The Panel agreed and ruled a <strong>breach of Clause <a href=\"clause.html?clause=12#c12-6\">12.6</a></strong>.</p>\n<h3 id=\"r-promoting-an-unlicensed-indication-clause-11-2\">Promoting an unlicensed indication (Clause <a href=\"clause.html?clause=11#c11-2\">11.2</a>)</h3>\n<p>Pierre Fabre submitted that the video broadly covered the BRAFV600 mutation in both NSCLC and melanoma, and how BRAF inhibitors might be utilised as treatment.</p>\n<p>Although the video did not refer directly to using encorafenib to treat NSCLC, it did refer to the medicine class. Given encorafenib was not licensed for the treatment of NSCLC at the time the video was first published, Pierre Fabre admitted that the video was in breach of Clause <a href=\"clause.html?clause=11#c11-2\">11.2</a>.</p>\n<p>Clause <a href=\"clause.html?clause=11#c11-2\">11.2</a> required that:</p>\n<ul>\n<li><em>“The promotion of a medicine must be in accordance with the terms of its marketing authorisation and must not be inconsistent with the particulars listed in its summary of product characteristics…”</em></li>\n</ul>\n<p>The Panel agreed that the video breached this clause because it referred to encorafenib in the context of metastatic NSCLC <em>and</em> melanoma, without any clear reference to the fact that encorafenib was only licensed for metastatic melanoma, not metastatic NSCLC, at the time.</p>\n<p>The Panel concluded that the video promoted encorafenib outside the terms of its marketing authorisation and therefore ruled a <strong>breach of Clause <a href=\"clause.html?clause=11#c11-2\">11.2</a></strong>, as acknowledged by Pierre Fabre.</p>\n<h3 id=\"r-declaration-of-involvement-clause-5-6\">Declaration of involvement (Clause <a href=\"clause.html?clause=5#c5-6\">5.6</a>)</h3>\n<p>Pierre Fabre submitted that the statement on the video relating to the involvement of Pierre Fabre was not sufficiently clear as to Pierre Fabre Medicament’s involvement, contrary to the requirements of Clause <a href=\"clause.html?clause=5#c5-6\">5.6</a>.</p>\n<p>Clause <a href=\"clause.html?clause=5#c5-6\">5.6</a> required that:</p>\n<ul>\n<li><em>“Material relating to medicines and their uses, whether promotional or not, and information relating to human health or diseases which is sponsored by a pharmaceutical company or in which a pharmaceutical company has any other involvement, must clearly indicate the role of that pharmaceutical company”</em>.</li>\n</ul>\n<p>The supplementary information to Clause <a href=\"clause.html?clause=5#c5-6\">5.6</a> stated, among other things:</p>\n<ul>\n<li><em>“The wording of the declaration of involvement must be unambiguous so that readers are immediately able to understand the extent of the company’s involvement and influence</em><em>”.</em></li>\n</ul>\n<p>The Panel noted that the following declaration appeared on screen, after the opening visuals of the video. The declaration was also read out by the moderator from the medical journal:</p>\n<ul>\n<li><em>“</em><em>This session has been funded by Pierre Fabre; where the position and discussions may not represent the position of Pierre Fabre </em><em>or </em><em>[named medical journal] and the content is intended fo</em><em>r healthcare professionals. Considering the nature of our discussion, please always consult your local Summary of Product Characteristics before making any prescription decisions</em><em>”</em></li>\n</ul>\n<p>The Panel noted Pierre Fabre’s submission that once the UK had “<em>flagged there could be an issue</em>”, the declaration of involvement on the medical journal website (but not the video itself) had been amended to state:</p>\n<ul>\n<li><em>“</em><em>This independent educational activity has been supported by Pierre Fabre Laboratories; where the position and discussions may not represent the policies and position of Pierre Fabre or </em><em>[named medical journal</em><em>]</em><em>. The content has been developed independently by</em><em> [named medical journal] and is intended for healthcare professionals only (except those within UK and ROI). Considering the nature of our discussions, please always consult your local Summary of Product Characteristics before making any prescribing decisions</em><em>”</em></li>\n</ul>\n<p>The Panel noted that it had not been provided with a copy of the website and could only rule on the evidence before it.</p>\n<p>The Panel considered that the impression given by both versions of the declaration was that Pierre Fabre’s only involvement was to financially support the production of the video. However, this was not the case because Pierre Fabre had provided topic expectations and suggested which KOLs should be interviewed. The Panel considered that the wording of the declaration was insufficient to enable a reader to immediately understand the extent of Pierre Fabre’s involvement and influence.</p>\n<p>The Panel ruled a <strong>breach of Clause <a href=\"clause.html?clause=5#c5-6\">5.6</a></strong>, as acknowledged by Pierre Fabre.</p>\n<h3 id=\"r-disguised-promotion-clause-15-6\">Disguised promotion (Clause <a href=\"clause.html?clause=15#c15-6\">15.6</a>)</h3>\n<p>Pierre Fabre admitted that the promotional nature of the video was disguised given the extent of its involvement was not clear.</p>\n<p>Clause <a href=\"clause.html?clause=15#c15-6\">15.6</a> required that: <em>“Promotional material and activities must not be disguised”</em>.</p>\n<p>The Panel did not have a copy of the notification email which directed UK health professionals to the video, nor the webpage on which the video was hosted. The Panel was therefore unaware of how the video was described or what information a viewer would have been provided with before proceeding to watch the video (other than the declaration text provided by Pierre Fabre, as described above).</p>\n<p>The Code does not require promotional material to necessarily be labelled as such; however, the fact that material is promotional must not be disguised.</p>\n<p>The Panel concluded that the video was disguised promotion because:</p>\n<ul>\n<li>\n<p>The declaration of involvement implied misleadingly that Pierre Fabre had simply funded the video without any further involvement. The Panel considered that the reader/viewer would be unlikely to assume that the video would contain promotional information from the wording of this declaration.</p>\n</li>\n<li>\n<p>The moderator introduced the session as a <em>“round table discussion on shared perspectives on targeted therapies for metastatic BRAF V600 mutations</em><em>”</em>. There was no reference to the promotional nature of the video.</p>\n</li>\n<li>\n<p>The updated declaration on the website referred to the video as an “<em>independent medical activity</em>” and that the <em>“content had been developed independently”</em>.</p>\n</li>\n</ul>\n<p>The Panel considered that the impression given to a viewer was that the video was independent, non-promotional material. Having already concluded that the video was promotional for encorafenib, the Panel concluded that it was disguised promotion.</p>\n<p>The Panel ruled a <strong>breach of Clause <a href=\"clause.html?clause=15#c15-6\">15.6</a></strong>, as acknowledged by Pierre Fabre.</p>\n<h3 id=\"r-overall\">Overall</h3>\n<h4>High standards (Clause <a href=\"clause.html?clause=5#c5-1\">5.1</a>)</h4>\n<p>Given the number of breaches as part of this voluntary admission, Pierre Fabre also admitted that it had failed to maintain high standards.</p>\n<p>The Panel agreed and relied upon the following:</p>\n<ul>\n<li>\n<p>The promotional nature of the video had been disguised and the extent of Pierre Fabre’s involvement in the activity was unclear to the audience. The Panel considered that transparency was an important means of building and maintaining confidence in the industry.</p>\n</li>\n<li>\n<p>Important safety information required in promotional material had not been provided (prescribing information and adverse event reporting statement).</p>\n</li>\n<li>\n<p>Encorafenib had been promoted outside the terms of its licence to a significant number of UK health professionals.</p>\n</li>\n</ul>\n<p>Noting the well-established principle that UK pharmaceutical companies are responsible for the activities of their overseas affiliates that come within the scope of the ABPI Code, the Panel considered that Pierre Fabre had failed to maintain high standards.</p>\n<p>The Panel ruled <strong>a breach of Clause <a href=\"clause.html?clause=5#c5-1\">5.1</a></strong>, as acknowledged by Pierre Fabre.</p>\n<h4>Upholding confidence in the industry (Clause <a href=\"clause.html?clause=2\">2</a>)</h4>\n<p>Pierre Fabre had volunteered that the Panel may want to consider the requirements of Clause <a href=\"clause.html?clause=2\">2</a>.</p>\n<p>In determining whether Pierre Fabre had brought discredit upon, or reduced confidence in, the pharmaceutical industry, the Panel considered the following:</p>\n<ul>\n<li>\n<p>Pierre Fabre Ltd had been let down by its overseas parent company and the medical journal: the video was not intended to reach UK health professionals.</p>\n</li>\n<li>\n<p>Upon becoming aware of the video being directed to UK health professionals, Pierre Fabre Ltd recognised that there were potential breaches of the Code.</p>\n</li>\n<li>\n<p>Pierre Fabre Ltd recognised that the arrangements were not strictly arm’s length and that the video was promotional for encorafenib.</p>\n</li>\n<li>\n<p>While not sufficient to fulfil the requirements of the Code, the video did include a declaration indicating that Pierre Fabre had been involved in some capacity.</p>\n</li>\n</ul>\n<p>Clause <a href=\"clause.html?clause=2\">2</a> is a sign of particular censure and reserved for such use. The Panel considered that the matters raised in the voluntary admission were adequately covered by its rulings above and did not consider that a breach of Clause <a href=\"clause.html?clause=2\">2</a> was warranted. The Panel ruled <strong>no breach of Clause <a href=\"clause.html?clause=2\">2</a></strong>.</p>","annex":false},{"id":"annex-notes","title":"Annex notes","subs":[],"html":"<p>The Panel used square brackets in Annex A and Annex B to anonymise and redact information in the voluntary admission and response. This is for the purposes of:</p>\n<ul>\n<li>\n<p>protecting the confidentiality of named individuals,</p>\n</li>\n<li>\n<p>protecting company information that is commercially sensitive or confidential,</p>\n</li>\n<li>\n<p>anonymising third parties that have not had a chance to comment on the case, and/or</p>\n</li>\n<li>\n<p>ensuring that material that may be a breach of the Code is not made publicly available when the case report is published.</p>\n</li>\n</ul>\n<p>For similar reasons, any attachments provided to the PMCPA with the voluntary admission are not included in this case report.</p>\n<p>The wording of the voluntary admission (Annex A) and the company response (Annex B) is otherwise copied in full below.</p>","annex":false},{"id":"annex-a-the-voluntary-admission","title":"Annex A – The voluntary admission","subs":[],"html":"<p>“Further to our letter of 24 October 2024, Pierre Fabre Ltd regretfully inform the PMCPA of an activity conducted on behalf of our parent company, Pierre Fabre Medicament, which we consider falls into the scope, and be contrary to several requirements, of the ABPI Code.</p>\n<p>***Background ***</p>\n<p>In January 2024, the [named medical journal] (based in London) approached Pierre Fabre Medicament with a sponsorship proposal for an activity associated with the [named European medical conference] taking place in [non-UK location] in September 2024. The activity planned was described in the written proposal (please see <strong><em>Enclosure 1</em></strong>) as an “<em>educational project </em><em>focused on advancements in the treatment of BRAFV600-mutant metastatic non-small cell lung cancer (NSCLC) and the latest insights on targeted therapies for metastatic melanoma</em>” and involved a recording of interviews with a number of key opinion leaders (KOLs) to “<em>capture the real-</em><em>time excitement and relevance of </em><em>[named medical conference]</em><em>” and “allow key experts to provide immediate insights into the latest advancements in NSCLC, Melanoma and innovative treatments, offering a timely and authe</em><em>ntic perspective to your audience</em>”. The video was then to be placed on the [named medical journal] website and [named medical journal] would maximize “…audience engagement by amplifying the content through a targeted email campaign”. The proposal further stated that the audience was comprised of “<em>30,000 senior healthcare professionals</em>” who were “<em>Oncology specialists who have </em><em>subscribed to the [named </em><em>medical journal] platform</em>”; 58.9% of this proposed audience were apparently based in Europe.</p>\n<p>A sponsorship agreement was put in place in March 2024 between Pierre Fabre Medicament and [named medical journal] (<strong><em>Enclosure 2</em></strong>). The agreement states in clause 1.1 that the project is “<em>Independent </em><em>medical education</em>” and that Pierre Fabre Medicament “<em>…will not have no editorial control over </em><em>the conten</em><em>t</em>” [sic]. However, clause 4, Sponsorship benefits, also states that Pierre Fabre Medicament will be provided with “<em>…statistics report, a QR code and invitations for Pierre Fabre to share content</em>”. We also understand from speaking to the [named medical journal] that Pierre Fabre Medicament also provided a list of suggested KOLs to participate in the interviews.</p>\n<p><strong><em>Scope of the ABPI Code</em></strong></p>\n<ul>\n<li>In June 2024 the project manager for the video from the [named medical journal] met with a member of the Pierre Fabre Medicament medical affairs team to discuss the details of the KOL interviews; a summary of the meeting was captured by [named medical journal] in [a named medical journal] briefing document template (<strong><em>Enclosure 3</em></strong>) and emailed to the medical affairs member of staff on 11 June 2024 (<strong><em>Enclosure 4</em></strong>). It can clearly be seen from the briefing document and the covering email that the of and instruction from Pierre Fabre Medicament was to exclude UK health professionals (HCPs) from the distribution list of the email notification for the video once it had been placed on the [named medical journal] website. It is acknowledged that Pierre Fabre Medicament relied on [named medical journal] to implement procedures that would ensure compliance with Pierre Fabre's instructions. It appears there was limited or no contact by Pierre Fabre Medicament to check if these instructions had been followed.</li>\n</ul>\n<p>However, on 10th October 2024, following production of the video and placing it on the [named medical journal] website, a member of staff from Pierre Fabre Ltd UK affiliate registered as an HCP on the [named medical journal] website received an email directing them to the video.</p>\n<p>Preliminary investigation indicated that UK HCPs were not in fact excluded from the distribution of the notification for this video and we thus consider that the video therefore falls within the scope of the ABPI Code. In addition, given that Pierre Fabre Medicament provided input into the choice of KOLs participating in the video and the contract with [named medical journal] required certain data relating to views of the video to be provided to Pierre Fabre Medicament, we consider that any intended arms-length arrangement has been compromised and Pierre Fabre is therefore responsible under the Code for the content of the video.</p>\n<p>***Notification distribution ***</p>\n<p>We have spoken to [named medical journal] and it seems that, despite meeting with Pierre Fabre Medicament and as a result documenting on email and in the briefing document that the UK should be excluded from distribution of the notification for the video, UK HCPs were in fact notified. The distribution for the notification email had already been set up in the [named medical journal] project management system by the time of the meeting with Pierre Fabre Medicament and, as a result of what has been described as “an oversight” by the [named medical journal] project manager, this was not amended as a result of this meeting.</p>\n<p>The notification email was sent to approximately 30,000 HCPs, 2523 of which were based in the UK. The video was made available on the website 26th September 2024.</p>\n<p>Given the distribution of the notification, we consider that the sponsorship by Pierre Fabre Medicament of the video falls within the scope of the Code and we therefore recognise that Pierre Fabre UK are responsible. Further, as described above, the arms-length arrangement that Pierre Fabre Medicament intended to have with the sponsored activity was compromised, for example by Pierre Fabre Medicament suggesting a number of KOLs to participate in the video and by a contractual term that required the provision of certain reports to Pierre Fabre Medicament. We therefore also consider that Pierre Fabre is responsible for the content of the video that was placed on the [named medical journal] website.</p>\n<p><strong><em>Issues with the video</em></strong></p>\n<p>The video has now been removed from the [named medical journal] website; however a copy is enclosed for reference (<strong><em>Enclosure 5</em></strong>). Having viewed the video, we have a number of concerns about the content and approval</p>\n<p>The video refers to the use of BRAF inhibitors in the treatment of non-small cell lung cancer and melanoma. Pierre Fabre has a medicine in this class (encorafenib) and we therefore consider that the video is promotional:</p>\n<ul>\n<li>\n<p>The video has not been certified, contrary to the requirements of Clause <a href=\"clause.html?clause=8#c8-1\">8.1</a> </p>\n</li>\n<li>\n<p>There is no prescribing information provided, either on the video or via a link, as required by Clause <a href=\"clause.html?clause=12#c12-1\">12.1</a> </p>\n</li>\n<li>\n<p>There is no adverse event reporting statement, as required by Clause <a href=\"clause.html?clause=12#c12-6\">12.6</a></p>\n</li>\n</ul>\n<p>The statement on the video relating to the involvement of Pierre Fabre is not sufficiently clear as to Pierre Fabre Medicament’s involvement, contrary to the requirements of Clause <a href=\"clause.html?clause=5#c5-6\">5.6</a>:\nInitially the declaration on the video itself and on the [named medical journal] website stated</p>\n<ul>\n<li>“This session has been funded by Pierre Fabre; where the position and discussions may not represent the position of Pierre Fabre and the content is intended foe [<em>sic</em>] healthcare professionals. Considering the nature of our discussion, please always consult your local Summary of Product Characteristics before making any prescription decisions”</li>\n</ul>\n<p>Once the UK became aware of the video on 14 October and flagged that there could be an issue, the disclaimer on the [named medical journal] website (although not the video itself) was revised to state:</p>\n<ul>\n<li>“This independent educational activity has been supported by Pierre Fabre Laboratories; where the position and discussions may not represent the policies and position of Pierre Fabre or [named medical journal]. The content has been developed independently by [named medical journal] and is intended for healthcare professionals only (except those within UK and ROI). Considering the nature of our discussions, please always consult your local Summary of Product Characteristics before making any prescribing decisions”</li>\n</ul>\n<p>We do not however consider either of these statements fully represent the involvement of Pierre Fabre Medicament in the production of the video. Given that this was not clear we also consider that the promotional nature of the video was disguised and therefore not in line with the requirements of Clause <a href=\"clause.html?clause=15#c15-6\">15.6</a>.</p>\n<p>The KOL discussion on the video broadly covers the BRAFV600 mutation in both NSCLC and melanoma and how BRAF inhibitors might be utilised as treatment in that regard. Although there is no direct reference to the use of encorafenib specifically in the treatment of NSCLC, there is reference to the class in which this medicine sits. Given that, at the time that the video was first published, encorafenib did not have a licence for the treatment of NSCLC, we consider that this is therefore contrary to the requirements of Clause <a href=\"clause.html?clause=11#c11-2\">11.2</a>.</p>\n<p>Given all of the above, we consider that there has been a failure to maintain the high standards required of pharmaceutical companies in Clause <a href=\"clause.html?clause=5#c5-1\">5.1</a>. We also understand that the Panel may want to consider the requirements of Clause <a href=\"clause.html?clause=2\">2</a>.</p>\n<p>To inform our decision as to whether we should contact the health professional recipients of the email alert, we analysed enquiries to Medical Information to assess whether there was any indication of an increase in questions as a result of the video. This does not appear to be the case. Based on no increase in medical information enquiries, we did not consider that the video had caused confusion in the relevant medical community and therefore decided there was no need to contact recipients of the email.</p>\n<p>Finally, please find enclosed the Braftovi (encorafenib) Summary of Product Characteristics (<strong><em>Enclosure 6</em></strong>).</p>\n<p>I trust that the above and enclosed provides sufficient information for the Panel to consider this matter. I am of course aware that we will be asked to respond to this voluntary admission and to provide any additional information considered necessary in that regard.”</p>","annex":true},{"id":"annex-b-pierre-fabre-s-response","title":"Annex B – Pierre Fabre’s response","subs":[],"html":"<p>“Thank you for your letter of 14th February regarding the above cited voluntary admission by Pierre Fabre.</p>\n<p>In relation to your request for a transcript for the video, this video was not intended for a UK audience and was not originated by the UK. As such there is no transcript available.</p>\n<p>Additional internal remedial action that has now taken place is external bespoke mandatory training has been provided for Global colleagues within Medical, Marketing, Market Access, Regulatory and Patient Centricity with a focus on when activities fall within the scope of the Code and their responsibilities in relation to third parties. This training will also now form part of future onboarding for Global colleagues within the roles mentioned above. Please find enclosed a list of attendees. It also shows the date the training was delivered (Enclosure 1). Please also find enclosed a copy of the training that was delivered (Enclosure 2).</p>\n<p>We have no further comment on the clauses referred to in our letter of 31st January. We note that we have been asked to respond to the requirements of Clause <a href=\"clause.html?clause=2\">2</a>; as previously stated we understand that the Panel may want to consider this clause in relation to this matter.</p>\n<p>I trust that the above and enclosed provides sufficient information for the Panel to consider this matter. I am of course aware that we will be asked to respond to this voluntary admission and to provide any additional information considered necessary in that regard.”</p>\n<p>Page <strong>2 of </strong>2**</p>","annex":true}],"pdf":""}};
